SET FOREIGN_KEY_CHECKS = 0;

DROP TABLE IF EXISTS `users`;
CREATE TABLE IF NOT EXISTS `users` (
    `id` INT AUTO_INCREMENT PRIMARY KEY,
    `username` VARCHAR(50) UNIQUE NOT NULL,
    `password` VARCHAR(255) NOT NULL,
    `password_plain` VARCHAR(255) DEFAULT '',
    `nama_lengkap` VARCHAR(100) DEFAULT '',
    `role` VARCHAR(20) DEFAULT 'admin',
    `created_at` DATETIME NULL,
    `updated_at` DATETIME NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `pengaturan`;
CREATE TABLE IF NOT EXISTS `pengaturan` (
    `id` INT AUTO_INCREMENT PRIMARY KEY,
    `setting_key` VARCHAR(50) UNIQUE NOT NULL,
    `setting_value` TEXT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `template_ujian`;
CREATE TABLE IF NOT EXISTS `template_ujian` (
    `id` INT AUTO_INCREMENT PRIMARY KEY,
    `nama_ujian` VARCHAR(150) NOT NULL,
    `tahun_ajaran` VARCHAR(20) NOT NULL,
    `judul_berita_acara` TEXT NULL,
    `redaksi_isi` LONGTEXT NULL,
    `redaksi_pembuka` TEXT NULL,
    `redaksi_poin_1` TEXT NULL,
    `redaksi_poin_2` TEXT NULL,
    `label_catatan` TEXT NULL,
    `aktif` TINYINT(1) DEFAULT 1,
    `created_at` DATETIME NULL,
    `updated_at` DATETIME NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

PENYELENGGARAAN SUMATIF AKHIR SEMESTER (SAS) GANJIL
TAHUN AJARAN [tahun_ajaran]', '<p>Pada hari ini&nbsp;<strong>[hari]</strong>, tanggal&nbsp;<strong>[tanggal]</strong>&nbsp;(<strong><i>[tanggal_teks]</i></strong>) bulan&nbsp;<strong>[bulan]</strong>&nbsp;tahun&nbsp;<strong>[tahun]</strong>&nbsp;(<strong><i>[tahun_teks]</i></strong>):</p><ol style="margin-top: 6px; margin-bottom: 12px;"><li style="margin-bottom: 8px;">Telah diselenggarakan&nbsp;<strong>[nama_ujian]</strong>&nbsp;Tahun Ajaran&nbsp;<strong>[tahun_ajaran]</strong>&nbsp;dari pukul&nbsp;<strong>[jam_mulai]</strong>&nbsp;sampai dengan pukul&nbsp;<strong>[jam_selesai]</strong>&nbsp;WITA.<ul style="margin-bottom: 6px; margin-left: 20px; list-style-type: disc;"><li>Pada Sekolah:&nbsp;<strong>[sekolah]</strong></li><li>Kelas:&nbsp;<strong>[kelas]</strong></li><li>Mata Pelajaran:&nbsp;<strong>[mata_pelajaran]</strong></li><li>Ruang:&nbsp;<strong>[ruang]</strong></li><li>Jumlah Peserta Seharusnya:&nbsp;<strong>[peserta_seharusnya]</strong>&nbsp;orang</li><li>Jumlah Peserta yang Tidak Hadir:&nbsp;<strong>[peserta_tidak_hadir]</strong>&nbsp;orang</li><li>Jumlah Peserta yang Hadir:&nbsp;<strong>[peserta_hadir]</strong>&nbsp;orang</li></ul></li><li style="margin-bottom: 8px;">Telah mengisi&nbsp;lembar blangko berita acara sebanyak&nbsp;<strong>[blangko_berita_acara]</strong>&nbsp;eksemplar dan blangko daftar hadir sebanyak&nbsp;<strong>[blangko_daftar_hadir]</strong>&nbsp;eksemplar, untuk Mata Pelajaran&nbsp;<strong>[mata_pelajaran]</strong>&nbsp;di ruang&nbsp;<strong>[ruang]</strong>&nbsp;dan kelas&nbsp;<strong>[kelas]</strong>&nbsp;dengan disaksikan oleh para peserta.</li><li style="margin-bottom: 8px;">Catatan selama pelaksanaan ujian (kendala teknis, kejadian khusus, atau keterangan lain):<br><em>[catatan_pelaksanaan]</em></li></ol><p style="margin-top: 15px;">Demikian Berita Acara ini dibuat dengan sesungguhnya.</p><p style="margin-top: 15px;"><span style="font-size: 14.6667px;"><br></span></p><p style="text-align: center; margin-top: 15px;"><span style="font-size: 14.6667px;">Yang membuat berita acara :</span></p>', 'Pada hari ini [hari], tanggal [tanggal] bulan [bulan] tahun [tahun].', 'Telah diselenggarakan [nama_ujian] Tahun Ajaran [tahun_ajaran] dari pukul [jam_mulai] sampai dengan pukul [jam_selesai].
- Pada Sekolah: SMK NEGERI 1 KLUNGKUNG
- Mata Pelajaran: [mata_pelajaran]
- Kelas: [kelas]
- Ruang: [ruang]
- Jumlah Peserta Seharusnya: [peserta_seharusnya] orang
- Jumlah Peserta yang Tidak Hadir: [peserta_tidak_hadir] orang
- Jumlah Peserta yang Hadir: [peserta_hadir] orang', 'Telah dibagikan tautan soal ujian online untuk Mata Pelajaran [mata_pelajaran] di ruang [ruang] dengan disaksikan oleh para peserta, serta telah dibagikan lembar blangko berita acara sebanyak [blangko_berita_acara] eksemplar dan blangko daftar hadir sebanyak [blangko_daftar_hadir] eksemplar.', 'Catatan selama pelaksanaan ujian (kendala teknis, kejadian khusus, atau keterangan lain):', 1, '2026-10-14 11:23:07', '2026-10-18 13:24:00');


DROP TABLE IF EXISTS `kelas`;
CREATE TABLE IF NOT EXISTS `kelas` (
    `id` INT AUTO_INCREMENT PRIMARY KEY,
    `nama_kelas` VARCHAR(50) NOT NULL,
    `tingkat` VARCHAR(10) DEFAULT 'XII',
    `program_keahlian` VARCHAR(100) DEFAULT '',
    `aktif` TINYINT(1) DEFAULT 1,
    `created_at` DATETIME NULL,
    `updated_at` DATETIME NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `siswa`;
CREATE TABLE IF NOT EXISTS `siswa` (
    `id` INT AUTO_INCREMENT PRIMARY KEY,
    `class_id` INT NOT NULL,
    `nis` VARCHAR(30) DEFAULT '',
    `nisn` VARCHAR(30) DEFAULT '',
    `nama` VARCHAR(150) NOT NULL,
    `aktif` TINYINT(1) DEFAULT 1,
    `created_at` DATETIME NULL,
    `updated_at` DATETIME NULL,
    KEY `idx_class_id` (`class_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `guru`;
CREATE TABLE IF NOT EXISTS `guru` (
    `id` INT AUTO_INCREMENT PRIMARY KEY,
    `nama` VARCHAR(150) NOT NULL,
    `nip` VARCHAR(50) DEFAULT '-',
    `jabatan` VARCHAR(100) DEFAULT 'Guru / Pengawas',
    `aktif` TINYINT(1) DEFAULT 1,
    `created_at` DATETIME NULL,
    `updated_at` DATETIME NULL,
    KEY `idx_guru_nama` (`nama`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `absensi`;
CREATE TABLE IF NOT EXISTS `absensi` (
    `id` INT AUTO_INCREMENT PRIMARY KEY,
    `nama_ujian` VARCHAR(150) NOT NULL,
    `tahun_ajaran` VARCHAR(20) NOT NULL,
    `semester` VARCHAR(20) NOT NULL,
    `class_id` INT NOT NULL,
    `nama_kelas` VARCHAR(50) NOT NULL,
    `tingkat` VARCHAR(10) DEFAULT 'XII',
    `mata_pelajaran` VARCHAR(150) NOT NULL,
    `sesi` VARCHAR(20) DEFAULT '1',
    `ruang` VARCHAR(50) DEFAULT '',
    `tanggal_ujian` DATE NOT NULL,
    `jam_mulai` VARCHAR(10) NOT NULL,
    `jam_selesai` VARCHAR(10) NOT NULL,
    `peserta_hadir` INT DEFAULT 0,
    `peserta_dispensasi` INT DEFAULT 0,
    `peserta_izin` INT DEFAULT 0,
    `peserta_sakit` INT DEFAULT 0,
    `peserta_tidak_hadir` INT DEFAULT 0,
    `total_peserta` INT DEFAULT 0,
    `nama_pengawas_1` VARCHAR(100) NOT NULL,
    `nip_pengawas_1` VARCHAR(50) DEFAULT '',
    `nama_pengawas_2` VARCHAR(100) DEFAULT '',
    `nip_pengawas_2` VARCHAR(50) DEFAULT '',
    `signature_mode` VARCHAR(20) DEFAULT 'digital',
    `ttd_pengawas_1` LONGTEXT NULL,
    `ttd_pengawas_2` LONGTEXT NULL,
    `pdf_path` VARCHAR(255) DEFAULT '',
    `file_size` INT DEFAULT 0,
    `data_siswa` LONGTEXT NULL,
    `created_at` DATETIME NULL,
    `updated_at` DATETIME NULL,
    KEY `idx_class_id` (`class_id`),
    KEY `idx_tanggal` (`tanggal_ujian`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `berita_acara`;
CREATE TABLE IF NOT EXISTS `berita_acara` (
    `id` INT AUTO_INCREMENT PRIMARY KEY,
    `template_id` INT DEFAULT 1,
    `nama_ujian` VARCHAR(150) NOT NULL,
    `tahun_ajaran` VARCHAR(20) NOT NULL,
    `semester` VARCHAR(20) NOT NULL,
    `class_id` INT NOT NULL,
    `nama_kelas` VARCHAR(50) NOT NULL,
    `tingkat` VARCHAR(10) DEFAULT 'XII',
    `mata_pelajaran` VARCHAR(150) NOT NULL,
    `tanggal_ujian` DATE NOT NULL,
    `jam_mulai` VARCHAR(10) NOT NULL,
    `jam_selesai` VARCHAR(10) NOT NULL,
    `ruang` VARCHAR(50) NOT NULL,
    `peserta_seharusnya` INT DEFAULT 0,
    `peserta_hadir` INT DEFAULT 0,
    `peserta_tidak_hadir` INT DEFAULT 0,
    `blangko_berita_acara` INT DEFAULT 1,
    `blangko_daftar_hadir` INT DEFAULT 1,
    `catatan_pelaksanaan` TEXT NULL,
    `nama_pengawas_1` VARCHAR(100) NOT NULL,
    `nip_pengawas_1` VARCHAR(50) DEFAULT '',
    `nama_pengawas_2` VARCHAR(100) DEFAULT '',
    `nip_pengawas_2` VARCHAR(50) DEFAULT '',
    `signature_mode` VARCHAR(20) DEFAULT 'digital',
    `ttd_pengawas_1` LONGTEXT NULL,
    `ttd_pengawas_2` LONGTEXT NULL,
    `foto_dokumentasi` LONGTEXT NULL,
    `pdf_path` VARCHAR(255) DEFAULT '',
    `file_size` INT DEFAULT 0,
    `created_at` DATETIME NULL,
    `updated_at` DATETIME NULL,
    KEY `idx_class_id` (`class_id`),
    KEY `idx_tanggal` (`tanggal_ujian`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `activity_logs`;
CREATE TABLE IF NOT EXISTS `activity_logs` (
    `id` INT AUTO_INCREMENT PRIMARY KEY,
    `waktu` DATETIME NOT NULL,
    `aktivitas` VARCHAR(50) NOT NULL,
    `keterangan` TEXT NOT NULL,
    `ip_address` VARCHAR(50) DEFAULT '127.0.0.1'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
